export const TOWNHOUSE_LOT_DATA_URI = "data:image/jpeg;base64,";
export const TOWNHOUSE_LOT_WIDTH = 500;
export const TOWNHOUSE_LOT_HEIGHT = 499;

// North row (housing frame, top-right slot) — same dir="up" orientation
// as the Mansion/Suburban House: native y=0 is the far-from-road content,
// native y=HEIGHT is nearest the road.
//
// This one arrived close to square (1105x970) instead of a tall vertical
// walk-up, so almost none of it needed trimming — the whole row of four
// townhouses is used as-is, same idea as how Trailer/Apartment show
// several repeated units within one lot's photo. Both edges were already
// clean (no half-cut trees/buildings), so no width crop either.
//
// Padded 60px past the gates (a flat repeat of the photo's own last few
// rows, which are already payment-toned) so the north sidewalk's hidden
// zone eats only the padding — without it, the gates would have landed
// roughly half inside that hidden zone.
//
// The chimneys are cut off at the photo's own top edge (as received) —
// nothing left to extend into, so the leftover depth above them (this
// lot's own natural height doesn't fill the full space above the road)
// falls back to a dark, roofline-toned color instead of the green used
// for the grassy lots, so it reads as shadow rather than an odd patch of
// lawn floating above the roof.
export const TOWNHOUSE_LOT_GROUND_STRIP_TOP = 0;
export const TOWNHOUSE_LOT_GROUND_STRIP_HEIGHT = 1;
